-- Expanded Psionics Handbook powers S.
-- Concise mechanical summaries; XPH remains the source of record.

WITH desired(slug,name,discipline,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,description,augmentation_text) AS (VALUES
('schism','Schism','telepathy',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'no',NULL,7,'Split your mind into two autonomous parts, allowing a second purely mental standard action each round at a reduced effective manifester level while sharing your power-point reserve.',NULL),
('second-chance','Second Chance','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level or until discharged',NULL,NULL,'no',NULL,9,'Once per round while the power lasts, reroll one attack roll, saving throw, ability check, or skill check and use the reroll.',NULL),
('sense-link','Sense Link','telepathy',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','One willing creature',NULL,NULL,'Concentration, up to 1 min./level',NULL,NULL,'no',NULL,1,'Perceive through one chosen sense of a willing subject while concentrating, using the subject’s sensory perspective and relevant sensory modifiers.','Spend 2 additional PP to reverse the direction of one linked sense; spend 4 additional PP to link a second sense.'),
('sense-link-forced','Sense Link, Forced','telepathy',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'Concentration, up to 1 min./level','will','Will negates','yes',NULL,3,'As sense link, but force the link onto a willing or unwilling creature; this version cannot be augmented.',NULL),
('sensitivity-to-psychic-impressions','Sensitivity to Psychic Impressions','clairsentience',NULL,'1 hour','other','Close (25 ft. + 5 ft./2 levels)',NULL,'Spread with radius 25 ft. + 5 ft./2 levels centered on you',NULL,'Concentration, up to 10 min./level',NULL,'None','no',NULL,3,'Read strong emotional impressions left in a location, revealing one significant past event for each 10 minutes of concentration within the power’s historical limit.',NULL),
('sequester-psionic','Sequester, Psionic','clairsentience',NULL,'1 standard action','standard','Touch','One willing creature or one object up to a 2-ft. cube/level touched',NULL,NULL,'One day/level (D)','will','None or Will negates (object)','conditional','No or Yes (object)',13,'Hide and suspend a willing creature or object as the sequester spell.','XP cost: 75 XP.'),
('shadow-body','Shadow Body','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,15,'Become a living shadow able to move across walls, ceilings, and liquids, gaining DR and multiple immunities/resistances while losing ordinary physical interaction.',NULL),
('share-pain','Share Pain','psychometabolism',NULL,'1 standard action','standard','Touch','You and one willing creature, or two willing creatures; see text',NULL,NULL,'1 hour/level (D)',NULL,NULL,'no',NULL,3,'Create a psychometabolic bond that divides hit point damage suffered by one designated subject between the linked creatures while they remain close enough.',NULL),
('share-pain-forced','Share Pain, Forced','psychometabolism',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 round/level (D)','fort','Fortitude negates','yes',NULL,5,'Force an unwilling creature to share half the hit point damage you suffer for a shorter duration.','Every 2 additional PP increases save DC by 1.'),
('shatter-mind-blank','Shatter Mind Blank','telepathy',NULL,'1 standard action','standard','30 ft.',NULL,'30-ft.-radius burst centered on you',NULL,'Instantaneous','will','Will negates','yes',NULL,9,'Attempt to end psionic mind blank or personal mind blank effects on targets that fail their saves and power resistance, using the class-defined manifester-level check.',NULL),
('skate','Skate','psychoportation',NULL,'1 standard action','standard','Personal or touch; see text','You, one willing creature, or one unattended object up to 100 lb./level; see text',NULL,NULL,'1 min./level (D)',NULL,'None','yes','Yes (harmless, object)',1,'Let a creature or object slide over solid ground as if on smooth ice; creatures gain enhanced land speed and objects become easier to drag.',NULL),
('solicit-psicrystal','Solicit Psicrystal','telepathy',NULL,'1 swift action','swift','Close (25 ft. + 5 ft./2 levels)','Your psicrystal',NULL,NULL,'1 round/level (D)',NULL,'No','no',NULL,5,'Transfer responsibility for concentrating on one of your powers to your psicrystal, freeing your own actions while the crystal maintains concentration.','Each additional PP increases maximum duration by 1 round.'),
('steadfast-perception','Steadfast Perception','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level (D)',NULL,NULL,'no',NULL,7,'Gain immunity to figments and glamers, +6 enhancement bonuses on Spot and Search, and a new save opportunity against recognized false sensory input.',NULL),
('stomp','Stomp','psychokinesis',NULL,'1 standard action','standard','20 ft.',NULL,'Cone-shaped spread',NULL,'Instantaneous','ref','Reflex negates','no',NULL,1,'Send a ground-hugging psychokinetic shock wave through the cone, knocking failed targets prone and dealing 1d4 nonlethal damage.','Each additional PP adds 1d4 nonlethal damage.'),
('strength-of-my-enemy','Strength of My Enemy','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'no',NULL,3,'Empower one natural or manufactured weapon to deal 1 Strength damage on each successful hit while granting you a corresponding enhancement bonus, subject to the per-foe cap.','Additional PP can raise the maximum Strength bonus and a 6-PP augmentation permits swift manifestation.'),
('suggestion-psionic','Suggestion, Psionic','telepathy','compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 hour/level or until completed','will','Will negates','yes',NULL,3,'Influence one creature as the suggestion spell.','Every 2 additional PP adds one nearby target.'),
('suspend-life','Suspend Life','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'Permanent unless ended or dismissed; see text',NULL,NULL,'no',NULL,11,'Enter an extremely deep trance that masks life and thought, slows your subjective metabolism dramatically, and ends only under the conditions defined by the power.',NULL),
('sustenance','Sustenance','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,3,'Manufacture enough internal nourishment to go without food and water for one day.',NULL),
('swarm-of-crystals','Swarm of Crystals','metacreativity','creation','1 standard action','standard','15 ft.',NULL,'Cone-shaped spread',NULL,'Instantaneous',NULL,'None','no',NULL,3,'Spray a cone of razorlike crystal shards that deals 3d4 slashing damage without a saving throw.','Each additional PP adds 1d4 damage.'),
('synesthete','Synesthete','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level (D)',NULL,NULL,'no',NULL,1,'Reroute sensory input so you can feel light or sound, gaining the power’s sensory bonuses and compensating for blindness or deafness under its rules.',NULL)
)
INSERT INTO dnd35_powers
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,discipline_id,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,augmentation_text,augmentation)
SELECT
  'xph-power-'||d.slug,'xph-3.5','Chapter 5',d.slug,d.name,d.description,d.description,0,NULL,1,
  'xph-power-discipline-'||d.discipline,d.subdiscipline,d.manifesting_time,d.action_type,d.range_text,
  d.target_text,d.area_text,d.effect_text,d.duration_text,d.save,d.saving_throw_text,
  d.power_resistance,d.power_resistance_text,d.power_points,d.augmentation_text,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_powers p
  WHERE p.slug=d.slug AND p.owner_user_id IS NULL
);
